// Deferred owner findings/current answers/late Bot API receipts, all fictional or loopback.
fn telegram_reconciliation_config()->Configuration{let mut v=queue_runtime_values();v.extend(telegram_values("http://127.0.0.1:54321"));Configuration::from_values(&v).unwrap()}
async fn telegram_reconcile_call(c:&mut PgConnection,q:&Value,input:Value)->Result<Value>{let config=telegram_reconciliation_config();let path=format!("/api/v1/execution/questions/{}/delivery-reconciliation",q["id"].as_str().unwrap());let route=automated_apply_agents::execution::route(&path).unwrap();automated_apply_agents::execution::dispatch_body_configured(c,route,"POST",None,input.to_string().as_bytes(),Some(&config)).await}
async fn telegram_uncertain_question()->(PgConnection,Value,Value,Value,TelegramSettings,TelegramIdentity){let(mut c,packet,intent,mut q,settings,identity)=telegram_question_fixture().await;q["state"]=json!("delivery_unknown");q["message_ids"]=json!([]);q["delivery_attempt"]=json!(Uuid::new_v4());q["delivery_lease"]=json!("2000-01-01T00:00:00Z");browser_save(&mut c,&format!("exec_q:{}",q["id"].as_str().unwrap()),q.clone()).await;(c,packet,intent,q,settings,identity)}
fn telegram_reconciliation_input(q:&Value,outcome:&str)->Value{json!({"expected_delivery_attempt":q["delivery_attempt"],"outcome":outcome,"message_id":if outcome=="sent"{json!(33)}else{Value::Null}})}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_owner_sent_finding_preserves_attempt_context_and_correlates_reply_without_claiming_provider_receipt(){
 let(mut c,_packet,_intent,q,settings,identity)=telegram_uncertain_question().await;let key=format!("exec_q:{}",q["id"].as_str().unwrap());let input=telegram_reconciliation_input(&q,"sent");let result=telegram_reconcile_call(&mut c,&q,input.clone()).await.unwrap();assert_eq!(result["state"],"sent");assert_eq!(result["resend_scheduled"],false);assert_eq!(result["application_receipt"],false);assert_eq!(result["reconciliation"]["provider_receipt_verified"],false);let saved=browser_pref(&mut c,&key).await;for name in ["expires_at","packet_revision","context_digest","delivery_attempt","delivery_binding"]{assert_eq!(saved[name],q[name],"{name}");}assert_eq!(saved["message_ids"],json!([33]));assert_eq!(telegram_reconcile_call(&mut c,&q,input.clone()).await.unwrap(),result);assert_eq!(browser_pref(&mut c,&key).await,saved);assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_answer(500,"Day")).await.unwrap());let answered=browser_pref(&mut c,&key).await;assert_eq!(answered["state"],"answered");assert_eq!(answered["provenance"]["source"],"owner_telegram");let replay=telegram_reconcile_call(&mut c,&q,input).await.unwrap();assert_eq!(replay["state"],"answered");assert_eq!(browser_pref(&mut c,&key).await,answered);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_owner_not_sent_finding_stays_non_pending_and_dashboard_answer_remains_available(){
 let(mut c,_packet,_intent,q,_settings,_identity)=telegram_uncertain_question().await;let key=format!("exec_q:{}",q["id"].as_str().unwrap());let result=telegram_reconcile_call(&mut c,&q,telegram_reconciliation_input(&q,"not_sent")).await.unwrap();assert_eq!(result["state"],"delivery_not_sent");assert_eq!(result["message_ids"],json!([]));assert_eq!(result["resend_scheduled"],false);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM rust_telegram_outbox").fetch_one(&mut c).await.unwrap(),0);let saved=browser_pref(&mut c,&key).await;assert_eq!(saved["expires_at"],q["expires_at"]);owner_question_call(&mut c,&owner_question_answer_path(&q),json!({"expected_revision":q["packet_revision"],"answer":"Day"})).await.unwrap();assert_eq!(browser_pref(&mut c,&key).await["state"],"answered");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_reconciliation_refuses_stale_attempt_binding_active_send_or_ambiguous_message_without_writes(){
 let(mut c,_packet,_intent,q,_settings,_identity)=telegram_uncertain_question().await;let key=format!("exec_q:{}",q["id"].as_str().unwrap());for index in 0..4{let mut changed=q.clone();let mut input=telegram_reconciliation_input(&q,"sent");let expected=match index{0=>{input["expected_delivery_attempt"]=json!(Uuid::new_v4());"telegram_delivery_attempt_conflict"},1=>{changed["delivery_binding"]=json!("f".repeat(64));"telegram_delivery_binding_required"},2=>{changed["delivery_lease"]=json!("2099-01-01T00:00:00Z");"telegram_delivery_lease_active"},_=>{let other=Uuid::new_v4();browser_save(&mut c,&format!("exec_q:{other}"),json!({"id":other,"message_ids":[33]})).await;"telegram_delivery_message_conflict"}};browser_save(&mut c,&key,changed.clone()).await;let before=browser_snapshot(&mut c).await;assert_eq!(telegram_reconcile_call(&mut c,&q,input).await.unwrap_err(),Failure(expected));assert_eq!(browser_snapshot(&mut c).await,before);}
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_reconciliation_keeps_first_owner_finding_immutable_and_refuses_altered_retry(){
 let(mut c,_packet,_intent,q,_settings,_identity)=telegram_uncertain_question().await;telegram_reconcile_call(&mut c,&q,telegram_reconciliation_input(&q,"sent")).await.unwrap();let before=browser_snapshot(&mut c).await;assert_eq!(telegram_reconcile_call(&mut c,&q,telegram_reconciliation_input(&q,"not_sent")).await.unwrap_err(),Failure("telegram_delivery_already_resolved"));let mut input=telegram_reconciliation_input(&q,"sent");input["message_id"]=json!(34);assert_eq!(telegram_reconcile_call(&mut c,&q,input).await.unwrap_err(),Failure("telegram_delivery_already_resolved"));assert_eq!(browser_snapshot(&mut c).await,before);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_reconciliation_suppressed_ack_rolls_back_finding_and_question(){
 let(mut c,_packet,_intent,q,_settings,_identity)=telegram_uncertain_question().await;let before=browser_snapshot(&mut c).await;sqlx::raw_sql("CREATE FUNCTION fixture_telegram_reconciliation_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'exec_q:') THEN RETURN NULL; END IF; RETURN NEW; END $$; CREATE TRIGGER fixture_telegram_reconciliation_drop BEFORE UPDATE ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_telegram_reconciliation_drop()").execute(&mut c).await.unwrap();let result=telegram_reconcile_call(&mut c,&q,telegram_reconciliation_input(&q,"not_sent")).await;sqlx::raw_sql("DROP TRIGGER fixture_telegram_reconciliation_drop ON owner_preferences; DROP FUNCTION fixture_telegram_reconciliation_drop()").execute(&mut c).await.unwrap();assert_eq!(result.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn queue_questions_allow_current_dashboard_answers_after_unknown_or_owner_not_sent_transport_outcome(){
 for state in ["delivery_unknown","delivery_not_sent"]{let(mut c,_work,mut q,resumes)=queue_question_fixture().await;q["state"]=json!(state);let key=format!("exec_q:{}",q["id"].as_str().unwrap());browser_save(&mut c,&key,q.clone()).await;let answer=queue_owner_answer(&mut c,&q,"Fictional Candidate",&resumes).await.unwrap();assert_eq!(answer["state"],"answered");assert_eq!(answer["reuse_approved"],false);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);}
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn unknown_question_siblings_follow_same_packet_answer_revision_without_resending_or_renewing(){
 let(mut c,packet,intent)=owner_question_packet().await;let q1=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][7]),Value::Null).await.unwrap();let mut q2=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][8]),Value::Null).await.unwrap();q2["state"]=json!("delivery_unknown");q2["delivery_attempt"]=json!(Uuid::new_v4());let key=format!("exec_q:{}",q2["id"].as_str().unwrap());browser_save(&mut c,&key,q2.clone()).await;owner_question_call(&mut c,&owner_question_answer_path(&q1),json!({"expected_revision":1,"answer":"Day"})).await.unwrap();let saved=browser_pref(&mut c,&key).await;assert_eq!(saved["state"],"delivery_unknown");assert_eq!(saved["packet_revision"],2);assert_eq!(saved["delivery_attempt"],q2["delivery_attempt"]);assert_eq!(saved["expires_at"],q2["expires_at"]);owner_question_call(&mut c,&owner_question_answer_path(&saved),json!({"expected_revision":2,"answer":"Email"})).await.unwrap();assert_eq!(browser_pref(&mut c,&key).await["state"],"answered");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_late_positive_bot_receipt_retains_conflicting_owner_not_sent_finding_without_repeat_send(){
 let(mut c,packet,intent)=owner_question_packet().await;telegram_question_binding(&mut c).await;let q=owner_question_call(&mut c,&owner_question_ask_path(&intent,&packet["fields"][7]),Value::Null).await.unwrap();let(gate,endpoint,transport_stop,transport_server)=question_transport_fixture(false).await;let mut values=queue_runtime_values();values.extend(telegram_values(&endpoint));let config=Arc::new(Configuration::from_values(&values).unwrap());let relay=telegram::prepare(&config).await.unwrap().unwrap();let stop=CancellationToken::new();let shutdown=stop.clone();let relay_config=config.clone();let running=tokio::spawn(async move{relay.run(&relay_config,Wake::default(),shutdown).await});tokio::time::timeout(Duration::from_secs(5),gate.entered.notified()).await.unwrap();let key=format!("exec_q:{}",q["id"].as_str().unwrap());let mut uncertain=browser_pref(&mut c,&key).await;uncertain["delivery_lease"]=json!("2000-01-01T00:00:00Z");browser_save(&mut c,&key,uncertain.clone()).await;telegram_reconcile_call(&mut c,&uncertain,telegram_reconciliation_input(&uncertain,"not_sent")).await.unwrap();gate.release.notify_one();let mut saved=Value::Null;for _ in 0..200{saved=browser_pref(&mut c,&key).await;if saved["delivery_receipt"]["message_id"]==33{break;}tokio::time::sleep(Duration::from_millis(10)).await;}assert_eq!(saved["state"],"sent");assert_eq!(saved["delivery_reconciliation"]["input"]["outcome"],"not_sent");assert_eq!(saved["delivery_reconciliation"]["provider_receipt_verified"],false);assert_eq!(saved["delivery_reconciliation_conflict"],"late_bot_receipt_differs_from_owner_report");assert_eq!(saved["delivery_receipt"]["source"],"bot_api_positive_receipt");assert_eq!(saved["message_ids"],json!([33]));assert_eq!(gate.sent.lock().await.len(),1);stop.cancel();assert!(running.await.unwrap().is_ok());transport_stop.cancel();transport_server.await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_historical_delivery_reconciliation_never_renews_expired_application_question(){
 let(mut c,_packet,_intent,mut q,settings,identity)=telegram_uncertain_question().await;q["expires_at"]=json!("2000-01-01T00:00:00Z");let key=format!("exec_q:{}",q["id"].as_str().unwrap());browser_save(&mut c,&key,q.clone()).await;telegram_reconcile_call(&mut c,&q,telegram_reconciliation_input(&q,"sent")).await.unwrap();let before=browser_pref(&mut c,&key).await;assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_answer(510,"Day")).await.unwrap());assert_eq!(browser_pref(&mut c,&key).await,before);let reply:String=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries WHERE update_id=510").fetch_one(&mut c).await.unwrap();assert!(reply.contains("context changed or paused"));assert_eq!(before["expires_at"],q["expires_at"]);
}
